import { google } from "googleapis"

// Read and write access: order rows are appended to the spreadsheet.
const SCOPES = ["https://www.googleapis.com/auth/spreadsheets"]

const getEnv = (name: string): string => {
    const value = process.env[name]
    if (!value) throw new Error(`Missing environment variable: ${name}`)
    return value
}

// Keys generated by Railway when splitting the service account JSON into
// separate environment variables.
const CREDENTIAL_KEYS = [
    "type",
    "project_id",
    "private_key_id",
    "private_key",
    "client_email",
    "client_id",
    "auth_uri",
    "token_uri",
    "auth_provider_x509_cert_url",
    "client_x509_cert_url",
    "universe_domain",
] as const

const buildCredentials = (): Record<string, string> => {
    const credentials: Record<string, string> = {}
    for (const key of CREDENTIAL_KEYS) {
        // Env vars flatten real newlines into literal "\n";
        // Google Auth requires them back as actual newlines.
        credentials[key] = key === "private_key"
            ? getEnv(key).replace(/\\n/g, "\n")
            : getEnv(key)
    }
    return credentials
}

// Lazily initialized so the module can be imported without credentials
// (e.g. during build) without throwing.
let sheets: ReturnType<typeof google.sheets> | undefined

export const getSheets = () => {
    if (!sheets) {
        const auth = new google.auth.GoogleAuth({
            credentials: buildCredentials(),
            scopes: SCOPES,
        })

        sheets = google.sheets({ version: "v4", auth })
    }

    return sheets
}

